import { createRepositories } from './composition/createRepositories';
import { createProjectController } from './composition/projectModule';
import { createTaskController } from './composition/taskModule';
import { createUserController } from './composition/userModule';
import { createApp } from './http/createApp';
import { UuidIdGenerator } from './id/UuidIdGenerator';

const port = Number(process.env.PORT ?? 3000);

const repositories = createRepositories();
const ids = new UuidIdGenerator();

const app = createApp([
  createUserController(repositories, ids).router,
  createProjectController(repositories, ids).router,
  createTaskController(repositories, ids).router,
]);

app.listen(port, () => {
  console.log(`Task management API listening on http://localhost:${port}`);
});

